export function envApiKeyAuth(name, envVars) {
    return {
        name,
        login: async (interaction) => {
            interaction.signal.throwIfAborted();
            const key = await interaction.prompt({ type: "secret", message: `Enter ${name}` });
            interaction.signal.throwIfAborted();
            return { type: "api_key", key };
        },
        resolve: async ({ ctx, credential, signal }) => {
            signal.throwIfAborted();
            if (credential?.key) {
                return { auth: { apiKey: credential.key }, env: credential.env, source: "stored credential" };
            }
            for (const envVar of envVars) {
                const value = await ctx.env(envVar);
                signal.throwIfAborted();
                if (value)
                    return { auth: { apiKey: value }, source: envVar };
            }
            return undefined;
        },
    };
}

export function lazyOAuth(input) {
    let promise;
    const loaded = () => {
        promise ??= input.load();
        return promise;
    };
    return {
        name: input.name,
        isSubscription: input.isSubscription,
        loginLabel: input.loginLabel,
        login: async (interaction, options) => (await loaded()).login(interaction, options),
        refresh: async (credential, signal) => (await loaded()).refresh(credential, signal),
        toAuth: async (credential) => (await loaded()).toAuth(credential),
    };
}

function base64urlEncode(bytes) {
    let binary = "";
    for (const byte of bytes) {
        binary += String.fromCharCode(byte);
    }
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}

export async function generatePKCE() {
    // Generate random verifier
    const verifierBytes = new Uint8Array(32);
    crypto.getRandomValues(verifierBytes);
    const verifier = base64urlEncode(verifierBytes);
    // Compute SHA-256 challenge
    const encoder = new TextEncoder();
    const data = encoder.encode(verifier);
    const hashBuffer = await crypto.subtle.digest("SHA-256", data);
    const challenge = base64urlEncode(new Uint8Array(hashBuffer));
    return { verifier, challenge };
}

function sendPage(response, status, html) {
    response.writeHead(status, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
    response.end(html);
}

export async function startOAuthCallbackServer(options) {
    const { providerName, signal } = options;
    if (signal?.aborted)
        throw new Error("Login cancelled");
    let resolveWait = () => { };
    let rejectWait = () => { };
    const waitPromise = new Promise((resolve, reject) => {
        resolveWait = resolve;
        rejectWait = reject;
    });
    // A cancelled or closed wait may never be observed.
    waitPromise.catch(() => undefined);
    let claimed = false;
    let settled = false;
    let timer;
    const onAbort = () => finish({ error: new Error("Login cancelled") });
    const finish = (result) => {
        if (settled)
            return;
        settled = true;
        if (timer)
            clearTimeout(timer);
        signal?.removeEventListener("abort", onAbort);
        if ("error" in result)
            rejectWait(result.error);
        else
            resolveWait(result.value);
    };
    const server = createServer((request, response) => {
        void (async () => {
            const url = new URL(request.url ?? "/", "http://localhost");
            if (request.method !== "GET" || url.pathname !== options.path) {
                sendPage(response, 404, oauthErrorHtml("Callback route not found."));
                return;
            }
            if (options.state !== undefined && url.searchParams.get("state") !== options.state) {
                sendPage(response, 400, oauthErrorHtml("State mismatch."));
                return;
            }
            if (claimed || settled) {
                sendPage(response, 409, oauthErrorHtml("This sign-in has already been handled."));
                return;
            }
            const error = url.searchParams.get("error");
            if (error) {
                const description = url.searchParams.get("error_description") ?? error;
                sendPage(response, 400, oauthErrorHtml(`${providerName} authorization failed.`, description));
                finish({ error: new Error(`${providerName} authorization failed: ${description}`) });
                return;
            }
            const code = url.searchParams.get("code");
            if (!code) {
                sendPage(response, 400, oauthErrorHtml("Missing authorization code."));
                return;
            }
            claimed = true;
            try {
                const value = await options.complete(code);
                sendPage(response, 200, oauthSuccessHtml(`Signed in to ${providerName}. You may now close this page.`));
                finish({ value });
            }
            catch (error) {
                const failure = error instanceof Error ? error : new Error(String(error));
                sendPage(response, 502, oauthErrorHtml(`${providerName} sign-in failed.`, failure.message));
                finish({ error: failure });
            }
        })();
    });
    await new Promise((resolve, reject) => {
        server.once("error", reject);
        server.listen(options.port, options.host, () => {
            server.off("error", reject);
            resolve();
        });
    });
    const address = server.address();
    if (!address || typeof address === "string") {
        server.close();
        throw new Error("OAuth callback server did not bind to TCP");
    }
    server.on("error", (error) => finish({ error }));
    signal?.addEventListener("abort", onAbort, { once: true });
    if (options.timeoutMs !== undefined) {
        timer = setTimeout(() => finish({ error: new Error(`${providerName} sign-in timed out`) }), options.timeoutMs);
    }
    const redirectHost = options.redirectHost ?? options.host;
    return {
        redirectUri: `http://${redirectHost.includes(":") ? `[${redirectHost}]` : redirectHost}:${address.port}${options.path}`,
        wait: () => waitPromise,
        cancel: () => {
            if (!claimed)
                finish({ value: undefined });
        },
        close: () => {
            finish({ error: new Error("OAuth callback server closed") });
            server.close();
        },
    };
}

export async function waitForCallbackOrManualInput(interaction, callback, prompt) {
    const manualAbort = new AbortController();
    let manualError;
    const manual = interaction
        .prompt({ type: "manual_code", ...prompt, signal: manualAbort.signal })
        .then((input) => {
        callback?.cancel();
        return input;
    })
        .catch((error) => {
        manualError = error instanceof Error ? error : new Error(String(error));
        callback?.cancel();
        return undefined;
    });
    try {
        const value = await callback?.wait();
        if (manualError)
            throw manualError;
        if (value !== undefined)
            return { type: "callback", value };
        const input = await manual;
        if (manualError)
            throw manualError;
        return { type: "manual", input: input ?? "" };
    }
    finally {
        manualAbort.abort();
    }
}

export function abortableSleep(ms, signal, cancelMessage) {
    return new Promise((resolve, reject) => {
        if (signal.aborted) {
            reject(new Error(cancelMessage));
            return;
        }
        const onAbort = () => {
            clearTimeout(timeout);
            reject(new Error(cancelMessage));
        };
        const timeout = setTimeout(() => {
            signal.removeEventListener("abort", onAbort);
            resolve();
        }, ms);
        signal.addEventListener("abort", onAbort, { once: true });
    });
}

export async function pollOAuthDeviceCodeFlow(options) {
    const deadline = typeof options.expiresInSeconds === "number"
        ? Date.now() + options.expiresInSeconds * 1000
        : Number.POSITIVE_INFINITY;
    let intervalMs = Math.max(MINIMUM_INTERVAL_MS, Math.floor((options.intervalSeconds ?? DEFAULT_POLL_INTERVAL_SECONDS) * 1000));
    let slowDownResponses = 0;
    if (options.waitBeforeFirstPoll) {
        const remainingMs = deadline - Date.now();
        if (remainingMs > 0) {
            await abortableSleep(Math.min(intervalMs, remainingMs), options.signal, CANCEL_MESSAGE);
        }
    }
    while (Date.now() < deadline) {
        if (options.signal.aborted) {
            throw new Error(CANCEL_MESSAGE);
        }
        const result = await options.poll();
        if (result.status === "complete") {
            return result.value;
        }
        if (result.status === "failed") {
            throw new Error(result.message);
        }
        if (result.status === "slow_down") {
            slowDownResponses += 1;
            // Use the server-provided interval when given (GitHub reports the new required minimum
            // in `interval`); trusting only a client-tracked value risks polling early forever under
            // WSL/VM clock drift. Otherwise apply RFC 8628 section 3.5: increase by 5 seconds.
            intervalMs =
                typeof result.intervalSeconds === "number" &&
                    Number.isFinite(result.intervalSeconds) &&
                    result.intervalSeconds > 0
                    ? Math.max(MINIMUM_INTERVAL_MS, Math.floor(result.intervalSeconds * 1000))
                    : Math.max(MINIMUM_INTERVAL_MS, intervalMs + SLOW_DOWN_INTERVAL_INCREMENT_MS);
        }
        const remainingMs = deadline - Date.now();
        if (remainingMs <= 0) {
            break;
        }
        await abortableSleep(Math.min(intervalMs, remainingMs), options.signal, CANCEL_MESSAGE);
    }
    throw new Error(slowDownResponses > 0 ? SLOW_DOWN_TIMEOUT_MESSAGE : TIMEOUT_MESSAGE);
}

export function registerBunOAuthFlows() {
    registerBundledOAuthFlowLoaders({
        anthropic: () => anthropicOAuth,
        openaiCodex: () => openaiCodexOAuth,
        openaiChatGPT: () => openaiChatGPTOAuth,
        githubCopilot: () => githubCopilotOAuth,
